insert into public.source_connectors(source_id,priority,label,connector_kind,config,enabled)
select source_id,priority,label,connector_kind,'{}'::jsonb,(connector_kind<>'unsupported') from c
on conflict (source_id,priority) do update set label=excluded.label,connector_kind=excluded.connector_kind,enabled=excluded.enabled,updated_at=now();

-- Connector-specific current public endpoints / filters.
update public.source_connectors set config='{"path":"/api/real-estate/list"}'::jsonb where source_id=5 and priority=1;
update public.source_connectors set config='{"path":"/properties"}'::jsonb where source_id=7 and priority=1;
update public.source_connectors set config=jsonb_build_object('url',(select search_url from public.sources where id=7)) where source_id=7 and priority=3;
update public.source_connectors set config='{"max_bytes":3000000,"candidate_url_regex":"/wohnungssuche/hamburg/"}'::jsonb where source_id=8 and priority between 1 and 3;
update public.source_connectors set config=jsonb_build_object('url',(select search_url from public.sources where id=11)) where source_id=11 and priority between 1 and 3;
update public.source_connectors set config=jsonb_build_object('url',(select search_url from public.sources where id=15)) where source_id=15 and priority in (1,3);
update public.source_connectors set config=jsonb_build_object('url',(select search_url from public.sources where id=17)) where source_id=17 and priority between 1 and 3;
update public.source_connectors set config=jsonb_build_object('url',(select search_url from public.sources where id=21),'candidate_url_regex','/wohnung-mieten/hamburg/') where source_id=21 and priority between 1 and 3;
update public.source_connectors set config='{"path":"/api/property-supply/all"}'::jsonb where source_id=33 and priority=1;
update public.source_connectors set config='{"path":"/wp-json/immo/v1/estates"}'::jsonb where source_id=37 and priority=1;
update public.source_connectors set config='{"path":"/wp-json/wp/v2/pages/9"}'::jsonb where source_id=54 and priority=2;
